def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list to track access order
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        keys_to_remove = []
        for key in cache:
            value, write_time = cache[key]
            if t >= write_time + ttl:
                keys_to_remove.append(key)

        for key in keys_to_remove:
            del cache[key]
            if key in lru_order:
                lru_order.remove(key)

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)

            # If cache is at capacity and key is not in cache, evict LRU
            if len(cache) >= capacity and key not in cache:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            cache[key] = (value, t)
            lru_order.append(key)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Entry is not expired (we already removed expired ones)
                results.append(value)
                # Make it most recently used
                lru_order.remove(key)
                lru_order.append(key)
            else:
                results.append(-1)

    return results

